    ["Groupes, duels et invocations acceptés ou refusés pour toi ; une interface plus calme."] = "Groups, duels and summons accepted or declined for you; a calmer interface.",
    ["Guerrier"] = "Warrior",
    ["Guerrier : Fulgurance, Vengeance, Exécution, Ivresse de la victoire. Voleur : Riposte. Chasseur : Contre-attaque, Morsure de la mangouste, Ordre de tuer. Paladin : Marteau de courroux. Exemple : tu pares un coup, Riposte apparaît avec sa touche. Coupé, ces sorts ne sont plus annoncés (sauf s'ils brillent et que « Sorts qui brillent » est actif)."] = "Warrior: Overpower, Revenge, Execute, Victory Rush. Rogue: Riposte. Hunter: Counterattack, Mongoose Bite, Kill Command. Paladin: Hammer of Wrath. Example: you parry a blow, Riposte appears with its key. When off, these spells are no longer announced (unless they glow and \"Glowing spells\" is on).",
    ["Guerrier : une petite icône quand le buff est actif."] = "Warrior: a small icon while the buff is active.",
    ["Guilde"] = "Guild",
    ["HDV"] = "AH",
    ["HDV : %s ne sera plus proposé (/pp hdv exclus pour la liste)"] = "AH: %s will no longer be offered (/pp hdv exclus for the list)",
    ["HDV : %s refusé"] = "AH: %s refused",
    ["HDV : %s refusé (%s)"] = "AH: %s refused (%s)",
    ["HDV : coche d'abord les objets à mettre en vente (clic sur la ligne)"] = "AH: first tick the items to post (click the row)",
    ["HDV : le jeu demande une confirmation pour %s. Clique encore (ou ta touche) pour confirmer."] = "AH: the game asks for confirmation for %s. Click again (or your key) to confirm.",
    ["HDV : le scan complet n'a rien renvoyé."] = "AH: the full scan returned nothing.",
    ["HDV : le serveur n'autorise un scan complet que toutes les 15 min, réessaie dans %d min."] = "AH: the server only allows a full scan every 15 min, try again in %d min.",
    ["HDV : pas de réponse au scan complet, réessaie plus tard."] = "AH: no answer to the full scan, try again later.",
    ["HDV : prix trouvés."] = "AH: prices found.",
    ["HDV : recherche des prix en cours, patiente un instant"] = "AH: price search in progress, please wait a moment",
    ["HDV : rien de prêt à mettre en vente"] = "AH: nothing ready to post",
    ["HDV : scan complet lancé (tous les prix de l'HDV, quelques secondes)..."] = "AH: full scan started (all AH prices, a few seconds)...",
    ["HDV : scan complet refusé par le jeu"] = "AH: full scan refused by the game",
    ["HDV : scan complet terminé, %d objet(s) avec un prix."] = "AH: full scan finished, %d item(s) with a price.",
    ["Hauteur de la barre"] = "Bar height",
    ["Healer suivi"] = "Tracked healer",
    ["Histoire de la quête"] = "Quest story",
    ["Hors combat"] = "Out of combat",
    ["Hors combat : boit la boisson la plus haute (eau, jus...) pour la mana. En combat : boit ta meilleure potion de mana. Remettre « aucune » coupe la touche."] = "Out of combat: drinks the best drink (water, juice...) for mana. In combat: drinks your best mana potion. Setting it back to \"none\" turns the key off.",
    ["Hors combat : l'icône du buff manquant avec le nom de l'allié."] = "Out of combat: the missing buff's icon with the ally's name.",
    ["Hors combat : l'icône du buff qui te manque et le nom de l'allié qui peut te le donner."] = "Out of combat: the icon of the buff you are missing and the name of the ally who can give it to you.",
    ["Hors combat : mange la nourriture la plus haute que tu peux utiliser. En combat : boit ta meilleure potion de soins. « La plus haute » = niveau requis, puis niveau de l'objet. Remettre « aucune » coupe la touche."] = "Out of combat: eats the best food you can use. In combat: drinks your best healing potion. \"Highest\" = required level, then item level. Setting it back to \"none\" turns the key off.",
    ["Hors combat · quête · rare"] = "Out of combat - quest - rare",
